-- v64 -> v65: retire the per-service reason codes (refactor RF-006c).
-- Codes name the situation, not the product, so a service can be replaced
-- without renaming codes (owner decision, 2026-11-06). Each retired code becomes
-- SERVICE_SETUP_INVALID, SERVICE_UNAVAILABLE or SERVICE_RESPONSE_INVALID. History
-- keeps which service it was: before a code is rewritten, the service it named
-- (and, for setup problems, the status) is added to the row's details.
-- Generated from docs/refactor/reason_code_proposals.py (RETIRED).
BEGIN IMMEDIATE;
CREATE TEMP TABLE nextgen_v65_guard(ok INTEGER CHECK(ok=1));
INSERT OR ROLLBACK INTO nextgen_v65_guard SELECT user_version=64 FROM pragma_user_version;

-- job_history: name the service the old code (or its cause) named, unless one is recorded.
UPDATE job_history SET details_json=json_set(COALESCE(details_json,'{}'),'$.service',
  CASE COALESCE(CASE WHEN reason_code IN ('DOWNLOAD_CLIENT_AUTH_FAILED','DOWNLOAD_CLIENT_RESPONSE_INVALID','DOWNLOAD_CLIENT_UNAVAILABLE','DOWNLOAD_CLIENT_UNSUPPORTED','JELLYFIN_CONFIGURATION_INVALID','JELLYFIN_UNAVAILABLE','KEEP_SERVICE_UNAVAILABLE','PROWLARR_AUTH_FAILED','PROWLARR_CONFIGURATION_INVALID','PROWLARR_SEARCH_REVIEW','PROWLARR_UNAVAILABLE','SHOKO_CONFIGURATION_INVALID','SHOKO_UNAVAILABLE','TORRENT_METADATA_CLIENT_UNSUPPORTED','TORRENT_METADATA_CONFIGURATION_INVALID','TORRENT_METADATA_UNAVAILABLE') THEN reason_code END,
   CASE WHEN json_valid(details_json) AND json_extract(details_json,'$.cause_reason_code') IN ('DOWNLOAD_CLIENT_AUTH_FAILED','DOWNLOAD_CLIENT_RESPONSE_INVALID','DOWNLOAD_CLIENT_UNAVAILABLE','DOWNLOAD_CLIENT_UNSUPPORTED','JELLYFIN_CONFIGURATION_INVALID','JELLYFIN_UNAVAILABLE','KEEP_SERVICE_UNAVAILABLE','PROWLARR_AUTH_FAILED','PROWLARR_CONFIGURATION_INVALID','PROWLARR_SEARCH_REVIEW','PROWLARR_UNAVAILABLE','SHOKO_CONFIGURATION_INVALID','SHOKO_UNAVAILABLE','TORRENT_METADATA_CLIENT_UNSUPPORTED','TORRENT_METADATA_CONFIGURATION_INVALID','TORRENT_METADATA_UNAVAILABLE') THEN json_extract(details_json,'$.cause_reason_code') END)
  WHEN 'DOWNLOAD_CLIENT_AUTH_FAILED' THEN 'qbittorrent'
  WHEN 'DOWNLOAD_CLIENT_RESPONSE_INVALID' THEN 'qbittorrent'
  WHEN 'DOWNLOAD_CLIENT_UNAVAILABLE' THEN 'qbittorrent'
  WHEN 'DOWNLOAD_CLIENT_UNSUPPORTED' THEN 'qbittorrent'
  WHEN 'JELLYFIN_CONFIGURATION_INVALID' THEN 'jellyfin'
  WHEN 'JELLYFIN_UNAVAILABLE' THEN 'jellyfin'
  WHEN 'KEEP_SERVICE_UNAVAILABLE' THEN 'sonarr'
  WHEN 'PROWLARR_AUTH_FAILED' THEN 'prowlarr'
  WHEN 'PROWLARR_CONFIGURATION_INVALID' THEN 'prowlarr'
  WHEN 'PROWLARR_SEARCH_REVIEW' THEN 'prowlarr'
  WHEN 'PROWLARR_UNAVAILABLE' THEN 'prowlarr'
  WHEN 'SHOKO_CONFIGURATION_INVALID' THEN 'shoko'
  WHEN 'SHOKO_UNAVAILABLE' THEN 'shoko'
  WHEN 'TORRENT_METADATA_CLIENT_UNSUPPORTED' THEN 'qbittorrent'
  WHEN 'TORRENT_METADATA_CONFIGURATION_INVALID' THEN 'qbittorrent'
  WHEN 'TORRENT_METADATA_UNAVAILABLE' THEN 'qbittorrent'
 END)
 WHERE (reason_code IN ('DOWNLOAD_CLIENT_AUTH_FAILED','DOWNLOAD_CLIENT_RESPONSE_INVALID','DOWNLOAD_CLIENT_UNAVAILABLE','DOWNLOAD_CLIENT_UNSUPPORTED','JELLYFIN_CONFIGURATION_INVALID','JELLYFIN_UNAVAILABLE','KEEP_SERVICE_UNAVAILABLE','PROWLARR_AUTH_FAILED','PROWLARR_CONFIGURATION_INVALID','PROWLARR_SEARCH_REVIEW','PROWLARR_UNAVAILABLE','SHOKO_CONFIGURATION_INVALID','SHOKO_UNAVAILABLE','TORRENT_METADATA_CLIENT_UNSUPPORTED','TORRENT_METADATA_CONFIGURATION_INVALID','TORRENT_METADATA_UNAVAILABLE')
        OR (json_valid(details_json) AND json_extract(details_json,'$.cause_reason_code') IN ('DOWNLOAD_CLIENT_AUTH_FAILED','DOWNLOAD_CLIENT_RESPONSE_INVALID','DOWNLOAD_CLIENT_UNAVAILABLE','DOWNLOAD_CLIENT_UNSUPPORTED','JELLYFIN_CONFIGURATION_INVALID','JELLYFIN_UNAVAILABLE','KEEP_SERVICE_UNAVAILABLE','PROWLARR_AUTH_FAILED','PROWLARR_CONFIGURATION_INVALID','PROWLARR_SEARCH_REVIEW','PROWLARR_UNAVAILABLE','SHOKO_CONFIGURATION_INVALID','SHOKO_UNAVAILABLE','TORRENT_METADATA_CLIENT_UNSUPPORTED','TORRENT_METADATA_CONFIGURATION_INVALID','TORRENT_METADATA_UNAVAILABLE')))
   AND json_extract(COALESCE(details_json,'{}'),'$.service') IS NULL;
UPDATE job_history SET details_json=json_set(COALESCE(details_json,'{}'),'$.service_status',
  CASE reason_code
  WHEN 'DOWNLOAD_CLIENT_AUTH_FAILED' THEN 'AUTH_FAILED'
  WHEN 'DOWNLOAD_CLIENT_UNSUPPORTED' THEN 'UNSUPPORTED'
  WHEN 'JELLYFIN_CONFIGURATION_INVALID' THEN 'NOT_CONFIGURED'
  WHEN 'PROVIDER_AUTH_FAILED' THEN 'AUTH_FAILED'
  WHEN 'PROVIDER_CONFIGURATION_INVALID' THEN 'NOT_CONFIGURED'
  WHEN 'PROWLARR_AUTH_FAILED' THEN 'AUTH_FAILED'
  WHEN 'PROWLARR_CONFIGURATION_INVALID' THEN 'NOT_CONFIGURED'
  WHEN 'SHOKO_CONFIGURATION_INVALID' THEN 'NOT_CONFIGURED'
  WHEN 'TORRENT_METADATA_CLIENT_UNSUPPORTED' THEN 'UNSUPPORTED'
  WHEN 'TORRENT_METADATA_CONFIGURATION_INVALID' THEN 'NOT_CONFIGURED'
 END)
 WHERE reason_code IN ('DOWNLOAD_CLIENT_AUTH_FAILED','DOWNLOAD_CLIENT_UNSUPPORTED','JELLYFIN_CONFIGURATION_INVALID','PROVIDER_AUTH_FAILED','PROVIDER_CONFIGURATION_INVALID','PROWLARR_AUTH_FAILED','PROWLARR_CONFIGURATION_INVALID','SHOKO_CONFIGURATION_INVALID','TORRENT_METADATA_CLIENT_UNSUPPORTED','TORRENT_METADATA_CONFIGURATION_INVALID')
   AND json_extract(COALESCE(details_json,'{}'),'$.service_status') IS NULL;

