-- A service wait no longer repeats its own code as the cause.
UPDATE job_history SET details_json=json_remove(details_json,'$.cause_reason_code')
 WHERE reason_code='SERVICE_UNAVAILABLE' AND json_valid(details_json)
   AND json_extract(details_json,'$.cause_reason_code')='SERVICE_UNAVAILABLE';
UPDATE event_history SET details_json=json_remove(details_json,'$.cause_reason_code')
 WHERE reason_code='SERVICE_UNAVAILABLE' AND json_valid(details_json)
   AND json_extract(details_json,'$.cause_reason_code')='SERVICE_UNAVAILABLE';

DROP TABLE nextgen_v65_guard;
PRAGMA user_version=65;
COMMIT;
